SELECT CASE WHEN balance >= 59000 THEN 'high' WHEN balance >= 7000 THEN 'mid' ELSE 'low' END AS balance_bucket, MIN(opened_date) AS first_opened_date, COUNT(balance) AS balance_count, ROUND(AVG(balance), 2) AS avg_balance FROM accounts WHERE balance IS NOT NULL AND (balance < 17000 OR status NOT IN ('FROZEN', 'OPEN')) GROUP BY CASE WHEN balance >= 59000 THEN 'high' WHEN balance >= 7000 THEN 'mid' ELSE 'low' END
